CREATE TABLE IF NOT EXISTS menu_categories (id TEXT PRIMARY KEY NOT NULL, title TEXT NOT NULL, source_flag_2 INTEGER NOT NULL DEFAULT 0, source_flag_3 INTEGER NOT NULL DEFAULT 0, position INTEGER NOT NULL, source_row_json TEXT);
CREATE TABLE IF NOT EXISTS menu_products (id TEXT PRIMARY KEY NOT NULL, title TEXT NOT NULL, price_minor INTEGER NOT NULL CHECK(price_minor >= 0), compare_price_minor INTEGER CHECK(compare_price_minor IS NULL OR compare_price_minor >= 0), image_url TEXT NOT NULL DEFAULT '', source_flag_6 INTEGER NOT NULL DEFAULT 0, source_text_7 TEXT NOT NULL DEFAULT '', source_options_json TEXT NOT NULL DEFAULT '[]', source_row_json TEXT);
CREATE TABLE IF NOT EXISTS menu_category_products (id TEXT PRIMARY KEY NOT NULL, category_id TEXT NOT NULL REFERENCES menu_categories(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES menu_products(id) ON DELETE CASCADE, position INTEGER NOT NULL, hidden INTEGER NOT NULL DEFAULT 0, UNIQUE(category_id, product_id));
CREATE TABLE IF NOT EXISTS coffee_notes (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, source_id TEXT UNIQUE, title TEXT NOT NULL, body TEXT NOT NULL, file_key TEXT, file_name TEXT, file_type TEXT, file_size INTEGER, encryption_key TEXT, encryption_iv TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS coffee_notes_owner_idx ON coffee_notes(user_id, created_at);
CREATE TABLE IF NOT EXISTS migration_identity_map (source_system TEXT NOT NULL, source_user_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, source_profile_id TEXT, PRIMARY KEY(source_system, source_user_id));
